from pathlib import Path
import json,html
P=Path(__file__).resolve().parent
rows=json.loads((P/'corpus_pa_v2.json').read_text('utf8'))['items']
compact=[{'id':r['item_id'],'name':r['name'],'family':r['family'],'daily':r['pa_daily']['value'],'dailyClass':r['pa_daily']['classification'],'act':r['pa_activation']['value'],'actClass':r['pa_activation']['classification'],'url':r['source_url'],'summary':r['mechanics_summary']} for r in rows]
encoded=json.dumps(compact,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
template=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calculadora PA R02 · TEST</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0e1321;color:#e6e9f4;font:15px/1.5 system-ui,Arial}main{max-width:820px;margin:auto;padding:20px}h1{font-size:27px;margin-bottom:3px}h2{font-size:20px}.muted,small{color:#acb7d2}.tag{background:#253d56;color:#d6efff;border-radius:12px;padding:3px 10px;display:inline-block}.panel{border:1px solid #39445c;border-radius:14px;padding:16px;margin:14px 0;background:#151c2d}.row{display:flex;gap:10px;flex-wrap:wrap}.row>*{flex:1;min-width:125px}label{display:block;font-size:13px;margin:8px 0 4px;color:#c9d1df}input,select,button{width:100%;border:1px solid #53617c;border-radius:8px;background:#232d41;color:#fff;padding:10px;font:inherit}button{cursor:pointer;background:#176081;border-color:#378fb4}a{color:#7acaf1}.record{display:flex;gap:8px;align-items:center;margin:7px 0;border-bottom:1px solid #2d364c;padding-bottom:7px}.record input{width:24px;flex-shrink:0}.record span{flex:1}.record code{font-size:11px;white-space:nowrap}.result{background:#0c2d38;padding:12px;border-radius:10px;white-space:pre-wrap}.warn{border-left:4px solid #dfa757;padding-left:10px;color:#e5cda3}.bad{color:#f6a0a0}.good{color:#a9ecc5}details{max-height:320px;overflow:auto}hr{border:0;border-top:1px solid #39445c}</style></head><body><main>
<div class="tag">MESTRE-SIDE · TEST · sem homologação</div><h1>Calculadora Universal de PA · R02</h1><p class="muted">Consulta offline de 95 fichas. O custo histórico nunca é modificado. O modo de cobrança diária ainda depende de decisão competente.</p>
<div class="panel"><h2>1. Censo histórico</h2><input id="filter" placeholder="Pesquisar nome ou família..."><details open><summary>Selecionar equipamentos</summary><div id="results"></div></details><div id="chosen" class="muted"></div></div>
<div class="panel"><h2>2. PA simultâneo</h2><div class="row"><div><label>PA Total</label><input id="total" type="number" min="0" value="300"></div><div><label>PA comprometido externo</label><input id="committed" type="number" min="0" value="80"></div></div><label>Hipótese de cobrança dos itens</label><select id="semantics"><option value="unknown">Não determinada (histórico)</option><option value="commit">SE os custos diários comprometerem PA</option><option value="debit">SE os custos diários forem debitados</option></select><button id="compute">Calcular cenário</button><pre id="result" class="result"></pre></div>
<div class="panel"><h2>3. Proposta paramétrica de item novo</h2><p class="muted">Coeficientes vazios não são considerados zero. Nenhuma das taxas abaixo foi cientificamente homologada.</p><div id="coeffs"></div><button id="quote">Estimar com coeficientes informados</button><pre id="proposal" class="result"></pre></div>
<div class="panel"><h2>Limitações científicas</h2><p class="warn">H1 possui um exemplo puro (+3 = 15 PA/dia), mas outros itens com +10 atributos e custos 20 ou 30 PA/dia contradizem uma soma não negativa automática de +5 por ponto.</p><p>Não converter MED, raridade, rank, cargas ou material em PA automaticamente. Não aplicar colapso de conjuração a falhas de equipamento sem regra competente. Fichas sem custo localizado NÃO custam zero.</p><small>Fontes: Notion Mestre, MAPA T-01, diretórios de inscrições e matrizes; compilação de 17/10/2026. HTML estático local, sem acesso à rede ou gravação no Notion.</small></div>
<script>const DB=__DATA__;let selected=new Set();const el=id=>document.getElementById(id);const fmt=x=>x===null?'PENDENTE':String(x);const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function render(){let q=el('filter').value.toLowerCase();el('results').innerHTML=DB.filter(x=>(x.name+' '+x.family).toLowerCase().includes(q)).map(x=>`<label class="record"><input type="checkbox" data-id="${x.id}" ${selected.has(x.id)?'checked':''}/><span><b>${escape(x.name)}</b><br><small>${escape(x.family)} · PA/dia ${fmt(x.daily)} (${x.dailyClass}) · PA/atv ${fmt(x.act)}</small></span><a target="_blank" rel="noopener" href="${x.url}">fonte</a></label>`).join('');document.querySelectorAll('#results input').forEach(x=>x.onchange=e=>{e.target.checked?selected.add(x.dataset.id):selected.delete(x.dataset.id);render()});el('chosen').textContent=selected.size+' ficha(s) selecionada(s)'}
el('filter').addEventListener('input',render);function num(id){let v=Number(el(id).value);return Number.isFinite(v)&&v>=0?v:null};
el('compute').onclick=()=>{let a=[...selected].map(id=>DB.find(x=>x.id===id)),t=num('total'),c=num('committed');if(t===null||c===null||c>t){el('result').textContent='Valores de PA inválidos';return};let known=a.filter(x=>x.daily!==null),unknown=a.filter(x=>x.daily===null),sum=known.reduce((acc,x)=>acc+x.daily,0),s=el('semantics').value;let lines=[`Itens: ${a.length}` ,`Subtotal histórico conhecido: ${sum} PA/dia`,`Custo diário sem número: ${unknown.length?unknown.map(x=>x.name).join('; '):'nenhum'}`,`PA livre antes dos itens: ${t-c}`];if(unknown.length)lines.push('TOTAL DIÁRIO = PENDENTE (não confundir subtotal com total)');if(s==='commit')lines.push(unknown.length?'Cenário compromisso INCOMPLETO':`SE comprometimento: PA livre após itens = ${t-c>=sum?t-c-sum:'INSUFICIENTE (sem aplicar consequência automática)'}`);else if(s==='debit')lines.push(unknown.length?'Cenário débito INCOMPLETO':`SE débito de PA do total inicial: saldo ilustrativo = ${t>=sum?t-sum:'INSUFICIENTE'} (não validado como recuperação/cobrança real)`);else lines.push('Sem regra de cobrança confirmada: nenhuma dedução sobre PA Livre');el('result').textContent=lines.join('\n')};
const fields=[['attribute','Bônus total de atributo','5','Somente hipótese H1, alterável'],['ca','Bônus CA','','Não calibrado'],['rd','Bônus RD','','Não calibrado'],['rdm','Bônus RDM','','Não calibrado'],['damage','Bônus fixo de dano','','Não calibrado'],['movement','Bônus de movimento (m)','','Não calibrado']];
el('coeffs').innerHTML=fields.map(([k,title,rate,ex])=>`<div class="row"><div><label>${title} · magnitude</label><input type="number" min="0" id="m_${k}" value="0"></div><div><label>PA/dia por unidade (cenário)</label><input type="number" min="0" step="any" id="r_${k}" value="${rate}" placeholder="Desconhecido"></div></div><small>${ex}</small>`).join('');
el('quote').onclick=()=>{let subtotal=0,missing=[],line=[];for(let [k,title] of fields){let v=num('m_'+k),raw=el('r_'+k).value;if(v===null){el('proposal').textContent='Magnitudes inválidas';return}if(v===0)continue;if(raw===''){missing.push(title);continue}let rate=num('r_'+k);if(rate===null){el('proposal').textContent='Taxas inválidas';return}let val=v*rate;subtotal+=val;line.push(`${title}: ${v} × ${rate} = ${val} PA/dia (assumido)`)}el('proposal').textContent=[...line,`Subtotal proposto sob hipóteses: ${subtotal} PA/dia`,`TOTAL: ${missing.length?'INDETERMINADO — faltam '+missing.join(', '):subtotal+' PA/dia (somente cenário)'}`,'ATIVAÇÃO: não estimada aqui; use fonte explícita ou engenharia de cenário na versão Python','CÂNONE: não alterado'].join('\n')}
render();el('compute').click();el('quote').click();</script></main></body></html>'''
(P/'CALCULADORA_MOBILE_OFFLINE.html').write_text(template.replace('__DATA__',encoded),encoding='utf8')
print('HTML bytes',(P/'CALCULADORA_MOBILE_OFFLINE.html').stat().st_size)
